        case .broadcast(let a0, let a1): return "{\"broadcast\":{" + ["\"id\":" + a0.leanJSON(), "\"raw\":" + a1.leanJSON()].joined(separator: ",") + "}}"
        }
    }
    static func fromLean(_ j: JSON?) -> Cmd? {
        guard let j else { return nil }
        guard let entry = j.onlyEntry else { return nil }
        let v = entry.value
        switch entry.key {
        case "preview":
            guard v.isObject, let a0 = Int.fromLean(v["id"]), let a1 = Entry.fromLean(v["form"]) else { return nil }
            return .preview(a0, a1)
        case "sign":
            guard v.isObject, let a0 = Draft.fromLean(v["d"]) else { return nil }
            return .sign(a0)
        case "broadcast":
            guard v.isObject, let a0 = Int.fromLean(v["id"]), let a1 = String.fromLean(v["raw"]) else { return nil }
            return .broadcast(a0, a1)
        default: return nil
        }
    }
}

