extension Entry: LeanCodable {
    func leanJSON() -> String {
        return "{" + ["\"destination\":" + destination.leanJSON(), "\"amount\":" + amount.leanJSON(), "\"priority\":" + priority.leanJSON()].joined(separator: ",") + "}"
    }
    static func fromLean(_ j: JSON?) -> Entry? {
        guard let j, j.isObject else { return nil }
        guard let destination = String.fromLean(j["destination"]), let amount = String.fromLean(j["amount"]), let priority = Priority.fromLean(j["priority"]) else { return nil }
        return Entry(destination: destination, amount: amount, priority: priority)
    }
}

extension Draft: LeanCodable {
    func leanJSON() -> String {
        return "{" + ["\"id\":" + id.leanJSON(), "\"form\":" + form.leanJSON(), "\"destination\":" + destination.leanJSON(), "\"script\":" + script.leanJSON(), "\"amount\":" + amount.leanJSON(), "\"fee\":" + fee.leanJSON(), "\"feeRateMilli\":" + feeRateMilli.leanJSON(), "\"feeRateText\":" + feeRateText.leanJSON(), "\"change\":" + change.leanJSON(), "\"inputs\":" + inputs.leanJSON()].joined(separator: ",") + "}"
    }
    static func fromLean(_ j: JSON?) -> Draft? {
        guard let j, j.isObject else { return nil }
        guard let id = Int.fromLean(j["id"]), let form = Entry.fromLean(j["form"]), let destination = String.fromLean(j["destination"]), let script = String.fromLean(j["script"]), let amount = Int.fromLean(j["amount"]), let fee = Int.fromLean(j["fee"]), let feeRateMilli = Int.fromLean(j["feeRateMilli"]), let feeRateText = String.fromLean(j["feeRateText"]), let change = Optional<Out>.fromLean(j["change"]), let inputs = [String].fromLean(j["inputs"]) else { return nil }
        return Draft(id: id, form: form, destination: destination, script: script, amount: amount, fee: fee, feeRateMilli: feeRateMilli, feeRateText: feeRateText, change: change, inputs: inputs)
    }
}

extension Signed: LeanCodable {
    func leanJSON() -> String {
        return "{" + ["\"draftId\":" + draftId.leanJSON(), "\"fee\":" + fee.leanJSON(), "\"changeAmount\":" + changeAmount.leanJSON(), "\"outputs\":" + outputs.leanJSON(), "\"inputs\":" + inputs.leanJSON(), "\"txid\":" + txid.leanJSON(), "\"raw\":" + raw.leanJSON()].joined(separator: ",") + "}"
    }
    static func fromLean(_ j: JSON?) -> Signed? {
        guard let j, j.isObject else { return nil }
        guard let draftId = Int.fromLean(j["draftId"]), let fee = Int.fromLean(j["fee"]), let changeAmount = Optional<Int>.fromLean(j["changeAmount"]), let outputs = [Out].fromLean(j["outputs"]), let inputs = [String].fromLean(j["inputs"]), let txid = String.fromLean(j["txid"]), let raw = String.fromLean(j["raw"]) else { return nil }
        return Signed(draftId: draftId, fee: fee, changeAmount: changeAmount, outputs: outputs, inputs: inputs, txid: txid, raw: raw)
    }
}

extension Priority: LeanCodable {
    func leanJSON() -> String {
        switch self {
        case .low: return "\"low\""
        case .medium: return "\"medium\""
        case .high: return "\"high\""
        }
    }
    static func fromLean(_ j: JSON?) -> Priority? {
        guard let j else { return nil }
        if case .string(let s) = j {
            switch s {
            case "low": return .low
            case "medium": return .medium
            case "high": return .high
            default: return nil
            }
        }
        guard let entry = j.onlyEntry else { return nil }
        switch entry.key {
        case "low": return .low
        case "medium": return .medium
        case "high": return .high
        default: return nil
        }
    }
}

extension Out: LeanCodable {
    func leanJSON() -> String {
        return "{" + ["\"value\":" + value.leanJSON(), "\"script\":" + script.leanJSON()].joined(separator: ",") + "}"
    }
    static func fromLean(_ j: JSON?) -> Out? {
        guard let j, j.isObject else { return nil }
        guard let value = Int.fromLean(j["value"]), let script = String.fromLean(j["script"]) else { return nil }
        return Out(value: value, script: script)
    }
}

// ---- elmgen judgment log: semantic decisions behind this translation (also printed to stderr at generation time) ----
// 1. CmdApp → CmdElmApp: `cmds` and `host` become static members; the runtime computes `cmds(msg, model)` from the pre-state, before `update`, exactly as `Session.step` does
// 2. inductive → enum with positional payloads
// 3. Cmd / Host types (and every type they contain) → LeanCodable: the JSON of Lean's derived ToJson / FromJson (structure → object of all fields, Option none → null and a missing Option key → none, constructor with fields → {"tag":{fields}}, nullary constructor → "tag", Nat → a number whose value is a natural with no fractional digits beyond the exponent)
// 4. structure → struct with the same fields; { m with f := v } → a fresh struct value
// 5. Nat → Int: Lean's Nat is unbounded, Swift's Int is 64-bit and traps on overflow (+ and * are mapped; literals are range-checked)
// 6. match → switch with the alternatives in source order (Lean's exhaustiveness guarantees Swift's); unused pattern variables print as _
// 7. let in tail position → Swift let; let / match in expression position → immediately applied closure
// 8. if-then-else on a decidable Prop → Swift Bool condition (the Decidable instance is erased)
// 9. Html constructors → Html<Msg>.ctor(…) of Runtime.swift (labels for button / field / toggle are the Lean binder names)
// 10. List → Array (value semantics; map / filter / count keep the order)
// 11. ButtonRole / TextStyle → the Runtime.swift enums of the same name
// 12. a :: b :: [] → array literal; a :: tail → [a] + tail
// 13. some x / none → Optional<T>.some(x) / Optional<T>.none (explicit T so nested options stay distinct)
// 14. Lean doc comments → Swift /// comments
// 15. nested constructor / Bool / Option patterns → nested Swift patterns
// 16. Bool not / and / or → ! && || (both operands are already evaluated values; && and || short-circuit, which is unobservable for pure code)
// 17. String.isEmpty / List.isEmpty → isEmpty
// 18. fun → Swift closure with explicit parameter and return types; an under-applied function is eta-expanded
// 19. toString (n : Nat) → String(n)
// 20. List.length → count
// 21. (String.trimAscii s).copy → leanTrimAscii(s) shim (strips ' ', \t, \r, \n at both ends, by code point)
// 22. = / == / != on String → unicodeScalars.elementsEqual (exact code points; Swift's String == uses canonical equivalence)
// 23. ++ on String / List → +
// 24. Option → Optional
// 25. List.all p → allSatisfy(p)
// 26. < ≤ > ≥ on Nat → the Swift comparison on Int
// 27. `Model`: no Lean DecidableEq, so no Swift Equatable; comparing its values is rejected
// 28. `Msg`: no Lean DecidableEq, so no Swift Equatable; comparing its values is rejected
// 29. `HostMsg`: no Lean DecidableEq, so no Swift Equatable; comparing its values is rejected
// 30. `Cmd`: no Lean DecidableEq, so no Swift Equatable; comparing its values is rejected
// 31. `Screen`: no Lean DecidableEq, so no Swift Equatable; comparing its values is rejected
// 32. `Entry`: Lean has DecidableEq but Swift gets no Equatable (Send.Entry has a field of type String (Swift's String == uses canonical equivalence, Lean's = is exact)); comparing its values is rejected
// 33. `Signed`: no Lean DecidableEq, so no Swift Equatable; comparing its values is rejected
// 34. `Draft`: no Lean DecidableEq, so no Swift Equatable; comparing its values is rejected
// 35. `Priority`: Lean DecidableEq → Swift Equatable (the synthesized == is exact for its fields)
// 36. `Out`: Lean has DecidableEq but Swift gets no Equatable (Send.Out has a field of type String (Swift's String == uses canonical equivalence, Lean's = is exact)); comparing its values is rejected
